cssLab.css:
/* هذا قسمك الحر. غيّره وجرب النتيجة. */
html { font-size: 16px; }
html, body { margin: 0; min-height: 100%; }
body { font-family: system-ui, sans-serif; background: #f6f8fb; padding: 12px; }
.lab-item { padding: 14px; background: #d1fae5; border: 1px solid #6ee7b7; border-radius: 8px; }

/* VLEX-LAB:START */
#lab-target {
  box-sizing: border-box;
  margin: 16px;
  padding: 24px;
  font-size: 18px;
  width: 480px;
  height: 240px;
  gap: 16px;
  border-radius: 12px;
  background-color: #ecfdf5;
  color: #12312b;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: stretch;
  flex-wrap: wrap;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
/* VLEX-LAB:END */
